CREATE TABLE private.image_company_rollout(company_id uuid PRIMARY KEY REFERENCES public.companies(id),enabled boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
ALTER TABLE private.image_company_rollout ENABLE ROW LEVEL SECURITY;
ALTER TABLE private.image_company_rollout FORCE ROW LEVEL SECURITY;
CREATE POLICY image_company_rollout_owner ON private.image_company_rollout TO postgres USING(true)WITH CHECK(true);
REVOKE ALL ON private.image_company_rollout FROM PUBLIC,anon,authenticated,service_role;
-- LOCAL CANDIDATE, not a hosted installer. No Auth/session/grant/activation.
CREATE TABLE private.image_inspector_companies(
 inspector_id uuid NOT NULL REFERENCES private.image_inspectors(user_id),
 company_id uuid NOT NULL REFERENCES public.companies(id),
 enabled boolean NOT NULL DEFAULT false,
 valid_until timestamptz NOT NULL,
 revoked_at timestamptz,
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(inspector_id,company_id)
);
ALTER TABLE private.image_inspector_companies ENABLE ROW LEVEL SECURITY;
ALTER TABLE private.image_inspector_companies FORCE ROW LEVEL SECURITY;
CREATE POLICY image_company_assignment_owner ON private.image_inspector_companies TO postgres USING(true)WITH CHECK(true);
REVOKE ALL ON private.image_inspector_companies FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION private.image_company_eligible(p_inspector uuid,p_company uuid)RETURNS boolean
 LANGUAGE sql STABLE SECURITY INVOKER SET search_path=''AS $$
 SELECT EXISTS(
  SELECT 1 FROM private.image_inspector_companies e
  JOIN private.image_inspectors i ON i.user_id=e.inspector_id
  JOIN private.company_controls c ON c.company_id=e.company_id AND c.state='active'
  WHERE e.inspector_id=p_inspector AND e.company_id=p_company
   AND e.enabled AND e.revoked_at IS NULL AND e.valid_until>clock_timestamp()
   AND EXISTS(SELECT 1 FROM private.image_company_rollout rollout JOIN private.company_controls control ON control.company_id=rollout.company_id AND control.state='active' WHERE rollout.company_id=e.company_id AND rollout.enabled) AND i.enabled AND i.valid_until>clock_timestamp()
 )AND NOT EXISTS(SELECT 1 FROM private.accounts a WHERE a.user_id=p_inspector AND a.state='active')
 AND NOT EXISTS(SELECT 1 FROM public.memberships m WHERE m.user_id=p_inspector)
 AND NOT EXISTS(SELECT 1 FROM private.audio_inspectors a WHERE a.user_id=p_inspector)
$$;
REVOKE ALL ON FUNCTION private.image_company_eligible(uuid,uuid)FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION private.image_catalog_authorize(p_company uuid, p_conversation uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$BEGIN
 PERFORM private.lock_accounts(ARRAY[auth.uid()]);
 IF NOT EXISTS(SELECT 1 FROM private.image_company_rollout rollout JOIN private.company_controls control ON control.company_id=rollout.company_id AND control.state='active' WHERE rollout.company_id=p_company AND rollout.enabled)OR NOT private.active_actor()OR NOT private.can_read_conversation(p_company,p_conversation)THEN RAISE EXCEPTION 'Image unavailable';END IF;
 RETURN jsonb_build_object('userId',auth.uid());
EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION USING errcode='P0001',message='Image unavailable';END$function$;
CREATE OR REPLACE FUNCTION private.read_messages_projection_v3(p_company uuid, p_conversation uuid, p_before bigint, p_after bigint, p_limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;
begin
 if not private.active_actor()or not private.can_read_conversation(p_company,p_conversation)or p_limit is null or p_limit not between 1 and 100 or(p_before is not null and p_before<1)or(p_after is not null and p_after<0)or(p_before is not null and p_after is not null)then raise exception 'Message action unavailable';end if;
 with page as materialized(select m.*,case when exists(select 1 from private.message_removals_all g where g.message_id=m.id and g.company_id=p_company and g.conversation_id=p_conversation)then'all'when exists(select 1 from private.message_removals_self s where s.user_id=auth.uid()and s.message_id=m.id and s.company_id=p_company and s.conversation_id=p_conversation)then'self'else null end removed_scope
 from public.messages m where m.company_id=p_company and m.conversation_id=p_conversation and(p_before is null or m.sequence<p_before)and(p_after is null or m.sequence>p_after)
 order by case when p_after is not null then m.sequence end asc,case when p_after is null then m.sequence end desc limit p_limit)
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'company_id',company_id,'conversation_id',conversation_id,'sender_id',sender_id,'sender_role',sender_role,'sequence',sequence,
 'accepted_at',to_char(accepted_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'kind',case when removed_scope is null then kind else'text'end,'body',case when removed_scope is null then body else'Mensagem removida'end,'important',case when removed_scope is null then important else false end,'removed_scope',removed_scope)
 order by case when p_after is not null then sequence end asc,case when p_after is null then sequence end desc),'[]'::jsonb)into result from page;
 return result;
exception when others then raise exception using errcode='P0001',message='Message action unavailable';end$function$;
CREATE OR REPLACE FUNCTION private.image_inspector_active()
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$BEGIN
 RETURN auth.jwt()->>'role'='authenticated'AND(auth.jwt()->>'exp')::numeric>extract(epoch FROM clock_timestamp())
 AND EXISTS(SELECT 1 FROM private.image_worker_settings w JOIN private.image_settings x ON x.singleton AND x.enabled WHERE w.singleton AND w.enabled AND w.decoder_image IS NOT NULL)
 AND EXISTS(SELECT 1 FROM private.image_inspectors i JOIN auth.sessions s ON s.user_id=i.user_id WHERE i.user_id=auth.uid()AND EXISTS(SELECT 1 FROM private.image_inspector_companies e WHERE e.inspector_id=i.user_id AND private.image_company_eligible(i.user_id,e.company_id))AND i.enabled AND i.valid_until>clock_timestamp()AND s.id=(auth.jwt()->>'session_id')::uuid AND(s.not_after IS NULL OR s.not_after>clock_timestamp()))
 AND NOT EXISTS(SELECT 1 FROM private.accounts WHERE user_id=auth.uid()AND state='active')AND NOT EXISTS(SELECT 1 FROM public.memberships WHERE user_id=auth.uid())AND NOT EXISTS(SELECT 1 FROM private.audio_inspectors WHERE user_id=auth.uid());
EXCEPTION WHEN OTHERS THEN RETURN false;END$function$;
CREATE OR REPLACE FUNCTION private.image_storage_allow(p_bucket text, p_name text, p_owner text, p_write boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a private.attachment_catalog;j private.image_inspection_jobs;metadata_op boolean;get_op boolean;g private.image_inspection_scopes;
BEGIN
 IF p_bucket IS DISTINCT FROM'connect-private-images'OR NOT EXISTS(SELECT 1 FROM private.image_worker_settings WHERE singleton AND storage_enabled)THEN RETURN false;END IF;
 SELECT * INTO STRICT a FROM private.attachment_catalog WHERE object_name=p_name AND media_kind='image'AND expected_bytes BETWEEN 1 AND 4194304;
 IF NOT EXISTS(SELECT 1 FROM private.image_company_rollout rollout JOIN private.company_controls control ON control.company_id=rollout.company_id AND control.state='active' WHERE rollout.company_id=a.company_id AND rollout.enabled)THEN RETURN false;END IF;
 IF p_write THEN
  RETURN storage.allow_only_operation('object.upload')AND p_owner=auth.uid()::text AND a.sender_id=auth.uid()AND a.session_id::text=auth.jwt()->>'session_id'AND a.state='reserved'AND private.active_actor()AND private.can_read_conversation(a.company_id,a.conversation_id)AND private.attachment_author_lock(a.sender_id,a.company_id,a.conversation_id,a.session_id,a.valid_until)AND EXISTS(SELECT 1 FROM private.image_settings WHERE singleton AND enabled);
 END IF;
 metadata_op:=storage.allow_only_operation('object.get_authenticated_info')OR storage.allow_only_operation('object.head_authenticated_info');
 get_op:=storage.allow_only_operation('object.get_authenticated');
 IF a.message_id IS NULL AND a.state IN('reserved','uploaded')AND a.sender_id=auth.uid()AND a.session_id::text=auth.jwt()->>'session_id'AND(metadata_op OR get_op)THEN
  RETURN private.active_actor()AND private.can_read_conversation(a.company_id,a.conversation_id)AND private.attachment_author_lock(a.sender_id,a.company_id,a.conversation_id,a.session_id,a.valid_until)AND EXISTS(SELECT 1 FROM private.image_settings WHERE singleton AND enabled);
 END IF;
 IF storage.allow_only_operation('s3.object.get')OR storage.allow_only_operation('s3.object.info')THEN
  IF a.state='uploaded'AND private.image_inspector_active()AND private.image_company_eligible(auth.uid(),a.company_id)THEN
   g:=private.image_authorized_scope(a.id);
   SELECT * INTO STRICT j FROM private.image_inspection_jobs WHERE attachment_id=a.id AND scope_id=g.id AND inspector_id=auth.uid()AND session_id::text=auth.jwt()->>'session_id'AND valid_until>clock_timestamp()AND result IS NULL AND decoder_image=(SELECT decoder_image FROM private.image_worker_settings WHERE singleton);
   RETURN private.attachment_author_lock(a.sender_id,a.company_id,a.conversation_id,a.session_id,a.valid_until);
  ELSIF a.state='ready'AND a.message_id IS NOT NULL THEN
   PERFORM private.image_message_resolve(a.company_id,a.conversation_id,a.message_id);RETURN true;
  END IF;
 END IF;
 RETURN false;
EXCEPTION WHEN OTHERS THEN RETURN false;END$function$;
CREATE OR REPLACE FUNCTION private.image_inspector_scope_guard()RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=''AS $$
BEGIN
 IF TG_OP='DELETE'THEN RAISE EXCEPTION 'Image scope unavailable';END IF;
 IF TG_OP='UPDATE'THEN
  IF(to_jsonb(new)-'revoked_at')IS DISTINCT FROM(to_jsonb(old)-'revoked_at')THEN RAISE EXCEPTION 'Image scope unavailable';END IF;
  IF old.revoked_at IS NOT NULL THEN
   IF new.revoked_at IS DISTINCT FROM old.revoked_at THEN RAISE EXCEPTION 'Image scope unavailable';END IF;
   RETURN old;
  END IF;
  IF new.revoked_at IS NULL THEN RETURN old;END IF;
  new.revoked_at:=clock_timestamp();RETURN new;
 END IF;
 new.issued_at:=clock_timestamp();new.issued_by:=current_user;
 IF new.revoked_at IS NOT NULL OR NOT EXISTS(
  SELECT 1 FROM private.image_inspectors i JOIN private.attachment_catalog a ON a.id=new.attachment_id AND a.company_id=new.company_id
  JOIN auth.sessions s ON s.id=new.session_id AND s.user_id=i.user_id
  WHERE i.user_id=new.inspector_id AND private.image_company_eligible(i.user_id,new.company_id)AND new.valid_until<=(SELECT e.valid_until FROM private.image_inspector_companies e WHERE e.inspector_id=i.user_id AND e.company_id=new.company_id)AND private.attachment_author_lock(a.sender_id,a.company_id,a.conversation_id,a.session_id,a.valid_until)AND a.media_kind='image'
   AND a.expected_sha256=new.sha256 AND a.expected_bytes=new.byte_length
   AND(s.not_after IS NULL OR s.not_after>clock_timestamp())
 )THEN RAISE EXCEPTION 'Image scope unavailable';END IF;
 RETURN new;
END$$;
CREATE OR REPLACE FUNCTION private.image_authorized_scope(p_attachment uuid)RETURNS private.image_inspection_scopes LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=''AS $$
DECLARE g private.image_inspection_scopes;
BEGIN
 IF NOT private.image_inspector_active()THEN RAISE EXCEPTION 'Image unavailable';END IF;
 SELECT x.* INTO STRICT g FROM private.image_inspection_scopes x
 JOIN private.image_inspectors i ON i.user_id=x.inspector_id AND private.image_company_eligible(i.user_id,x.company_id)
 JOIN private.attachment_catalog a ON a.id=x.attachment_id AND a.company_id=x.company_id AND a.media_kind='image'
 JOIN private.image_worker_settings w ON w.singleton AND w.decoder_image=x.decoder_image
 WHERE x.inspector_id=auth.uid()AND x.session_id::text IS NOT DISTINCT FROM auth.jwt()->>'session_id'
  AND x.attachment_id=p_attachment AND x.revoked_at IS NULL AND clock_timestamp()>=x.valid_from AND clock_timestamp()<x.valid_until
  AND a.expected_sha256=x.sha256 AND a.expected_bytes=x.byte_length
 FOR SHARE OF x;
 RETURN g;
EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION USING errcode='P0001',message='Image unavailable';END$$;
CREATE OR REPLACE FUNCTION private.image_claim(p_attachment uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=''AS $$
DECLARE a private.attachment_catalog;j private.image_inspection_jobs;i private.image_inspectors;pin text;until_at timestamptz;g private.image_inspection_scopes;
BEGIN
 SELECT * INTO STRICT i FROM private.image_inspectors WHERE user_id=auth.uid()FOR UPDATE;

 IF NOT private.image_inspector_active()THEN RAISE EXCEPTION 'Image unavailable';END IF;
 IF p_attachment IS NULL THEN
  SELECT * INTO g FROM private.image_inspection_scopes
   WHERE inspector_id=i.user_id AND revoked_at IS NULL FOR UPDATE;
  IF FOUND THEN
   SELECT * INTO j FROM private.image_inspection_jobs WHERE scope_id=g.id FOR UPDATE;
   IF g.valid_until>clock_timestamp()AND(j.attachment_id IS NULL OR j.valid_until>clock_timestamp())THEN
    -- Never steal another live session, or revoke a finished lease while ACK replay is valid.
    IF g.session_id::text IS DISTINCT FROM auth.jwt()->>'session_id'THEN RAISE EXCEPTION 'Image unavailable';END IF;
    IF j.attachment_id IS NULL OR j.result IS NOT NULL THEN RETURN NULL;END IF;
    p_attachment:=g.attachment_id;
   ELSE
    UPDATE private.image_inspection_scopes SET revoked_at=clock_timestamp()WHERE id=g.id;
   END IF;
  END IF;
  IF p_attachment IS NULL THEN
   SELECT candidate.id INTO p_attachment FROM private.attachment_catalog candidate
    WHERE private.image_company_eligible(i.user_id,candidate.company_id)AND candidate.media_kind='image'AND candidate.state='uploaded'
     AND candidate.valid_until>clock_timestamp()AND candidate.expected_sha256=candidate.observed_sha256 AND candidate.expected_bytes=candidate.observed_bytes
     AND EXISTS(SELECT 1 FROM storage.objects o WHERE o.bucket_id='connect-private-images'AND o.name=candidate.object_name AND o.owner_id=candidate.sender_id::text)
     AND NOT EXISTS(SELECT 1 FROM private.image_inspection_jobs queued_job WHERE queued_job.attachment_id=candidate.id AND(queued_job.result IS NOT NULL OR queued_job.valid_until>clock_timestamp()OR queued_job.attempts>=3))
     AND private.attachment_author_lock(candidate.sender_id,candidate.company_id,candidate.conversation_id,candidate.session_id,candidate.valid_until)
    ORDER BY candidate.valid_until,candidate.id LIMIT 1;
   IF p_attachment IS NULL THEN RETURN NULL;END IF;
   INSERT INTO private.image_inspection_scopes(inspector_id,company_id,attachment_id,session_id,sha256,byte_length,decoder_image,valid_from,valid_until)
    SELECT i.user_id,candidate.company_id,candidate.id,(auth.jwt()->>'session_id')::uuid,candidate.expected_sha256,candidate.expected_bytes,w.decoder_image,
     clock_timestamp(),least(clock_timestamp()+interval'30 seconds',candidate.valid_until,i.valid_until,(SELECT e.valid_until FROM private.image_inspector_companies e WHERE e.inspector_id=i.user_id AND e.company_id=candidate.company_id),to_timestamp((auth.jwt()->>'exp')::double precision))
    FROM private.attachment_catalog candidate CROSS JOIN private.image_worker_settings w WHERE candidate.id=p_attachment AND w.singleton;
  END IF;
 END IF;
 g:=private.image_authorized_scope(p_attachment);
 SELECT decoder_image INTO STRICT pin FROM private.image_worker_settings WHERE singleton;
 IF EXISTS(SELECT 1 FROM private.image_inspection_jobs WHERE inspector_id=i.user_id AND result IS NULL AND valid_until>clock_timestamp()AND attachment_id<>p_attachment)THEN RAISE EXCEPTION 'Image unavailable';END IF;
 SELECT * INTO STRICT a FROM private.attachment_catalog WHERE id=p_attachment AND media_kind='image'AND company_id=g.company_id;
 IF NOT private.attachment_author_lock(a.sender_id,a.company_id,a.conversation_id,a.session_id,a.valid_until)THEN RAISE EXCEPTION 'Image unavailable';END IF;
 SELECT * INTO STRICT a FROM private.attachment_catalog WHERE id=p_attachment AND state='uploaded'AND observed_sha256=expected_sha256 AND observed_bytes=expected_bytes FOR UPDATE;
 IF NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='connect-private-images'AND name=a.object_name AND owner_id=a.sender_id::text)THEN RAISE EXCEPTION 'Image unavailable';END IF;
 SELECT * INTO j FROM private.image_inspection_jobs WHERE attachment_id=a.id FOR UPDATE;
 IF FOUND AND j.result IS NOT NULL THEN RAISE EXCEPTION 'Image unavailable';END IF;
 IF j.valid_until>clock_timestamp()THEN
  IF j.scope_id IS DISTINCT FROM g.id OR j.inspector_id<>i.user_id OR j.session_id::text IS DISTINCT FROM auth.jwt()->>'session_id'OR j.decoder_image<>pin THEN RAISE EXCEPTION 'Image unavailable';END IF;
 ELSE
  IF j.attempts>=3 THEN RAISE EXCEPTION 'Image unavailable';END IF;
  until_at:=least(clock_timestamp()+interval'30 seconds',a.valid_until,i.valid_until,g.valid_until,to_timestamp((auth.jwt()->>'exp')::double precision));
  INSERT INTO private.image_inspection_jobs(attachment_id,lease_id,inspector_id,session_id,valid_until,decoder_image,attempts,result,scope_id)VALUES(a.id,gen_random_uuid(),i.user_id,(auth.jwt()->>'session_id')::uuid,until_at,pin,1,NULL,g.id)
  ON CONFLICT(attachment_id)DO UPDATE SET lease_id=excluded.lease_id,inspector_id=excluded.inspector_id,session_id=excluded.session_id,valid_until=excluded.valid_until,decoder_image=excluded.decoder_image,attempts=private.image_inspection_jobs.attempts+1,result=NULL,scope_id=excluded.scope_id RETURNING * INTO j;
  INSERT INTO private.image_lease_events(attachment_id,lease_id,event,scope_id)VALUES(a.id,j.lease_id,'claimed',g.id);
 END IF;
 RETURN jsonb_build_object('attachmentId',a.id,'leaseId',j.lease_id,'validUntil',j.valid_until,'companyId',a.company_id,'conversationId',a.conversation_id,'objectKey',a.object_name,'sha256',encode(a.expected_sha256,'hex'),'byteLength',a.expected_bytes,'decoderImage',j.decoder_image);
EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION USING errcode='P0001',message='Image unavailable';END$$;
CREATE OR REPLACE FUNCTION private.image_finish(p_attachment uuid,p_lease uuid,p_digest text,p_bytes integer,p_pass boolean,p_type text,p_width integer,p_height integer,p_decoder text)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=''AS $$
DECLARE a private.attachment_catalog;j private.image_inspection_jobs;proof jsonb;r jsonb;g private.image_inspection_scopes;
BEGIN
 PERFORM 1 FROM private.image_inspectors WHERE user_id=auth.uid()FOR UPDATE;
 g:=private.image_authorized_scope(p_attachment);
 IF p_lease IS NULL OR p_pass IS NULL THEN RAISE EXCEPTION 'Image unavailable';END IF;
 SELECT * INTO STRICT a FROM private.attachment_catalog WHERE id=p_attachment AND media_kind='image'AND company_id=g.company_id;
 IF NOT private.attachment_author_lock(a.sender_id,a.company_id,a.conversation_id,a.session_id,a.valid_until)THEN RAISE EXCEPTION 'Image unavailable';END IF;
 SELECT * INTO STRICT a FROM private.attachment_catalog WHERE id=p_attachment FOR UPDATE;
 SELECT * INTO STRICT j FROM private.image_inspection_jobs WHERE attachment_id=a.id FOR UPDATE;
 IF j.scope_id IS DISTINCT FROM g.id OR j.lease_id IS DISTINCT FROM p_lease OR j.inspector_id<>auth.uid()OR j.session_id::text IS DISTINCT FROM auth.jwt()->>'session_id'OR j.valid_until<=clock_timestamp()OR j.decoder_image IS DISTINCT FROM p_decoder OR p_decoder IS DISTINCT FROM(SELECT decoder_image FROM private.image_worker_settings WHERE singleton)THEN RAISE EXCEPTION 'Image unavailable';END IF;
 proof:=jsonb_build_object('sha256',p_digest,'byteLength',p_bytes,'pass',p_pass,'mime',p_type,'width',p_width,'height',p_height,'decoderImage',p_decoder);
 IF j.result IS NOT NULL THEN
  IF j.result<>proof THEN RAISE EXCEPTION 'Image unavailable';END IF;
  RETURN jsonb_build_object('state',a.state);
 END IF;
 IF a.state<>'uploaded'OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='connect-private-images'AND name=a.object_name AND owner_id=a.sender_id::text)THEN RAISE EXCEPTION 'Image unavailable';END IF;
